function validate([strs]) {
  if (!Array.isArray(strs) || strs.length < 1 || strs.length > 300) return 'strs needs 1 to 300 words.';
  const len = strs[0].length;
  if (len < 1 || len > 300) return 'Each word has 1 to 300 letters.';
  const key = (w) => w.split('').sort().join('');
  const first = key(strs[0]);
  for (const w of strs) {
    if (typeof w !== 'string' || !/^[a-z]+$/.test(w)) return 'Words use lowercase letters only.';
    if (w.length !== len) return 'All words must have the same length.';
    if (key(w) !== first) return 'All words must be anagrams of each other.';
  }
  return null;
}

