function numSimilarGroups(strs) {
  const n = strs.length;
  const parent = Array.from({ length: n }, (_, i) => i);

  const find = (x) => {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  };

  const similar = (a, b) => {
    let diff = 0;
    for (let k = 0; k < a.length; k++) {
      if (a[k] !== b[k]) {
        diff++;
        if (diff > 2) return false;
      }
    }
    return true;
  };

  let groups = n;
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      if (!similar(strs[i], strs[j])) continue;
      const rootI = find(i);
      const rootJ = find(j);
      if (rootI !== rootJ) {
        parent[rootI] = rootJ;
        groups--;
      }
    }
  }
  return groups;
}

