function numSimilarGroups(strs) {
  // Similar means: equal, or some single swap of two positions turns one into the other.
  const isSimilar = (a, b) => {
    if (a === b) return true;
    const chars = a.split('');
    for (let i = 0; i < chars.length; i++)
      for (let j = i + 1; j < chars.length; j++) {
        const copy = chars.slice();
        [copy[i], copy[j]] = [copy[j], copy[i]];
        if (copy.join('') === b) return true;
      }
    return false;
  };
  const seen = new Array(strs.length).fill(false);
  let count = 0;
  for (let start = 0; start < strs.length; start++) {
    if (seen[start]) continue;
    count++;
    const stack = [start];
    seen[start] = true;
    while (stack.length) {
      const cur = stack.pop();
      for (let other = 0; other < strs.length; other++)
        if (!seen[other] && isSimilar(strs[cur], strs[other])) { seen[other] = true; stack.push(other); }
    }
  }
  return count;
}

