function generate(rand, size) {
  let n, len, alphabet;
  if (size === 'large') {
    if (rand() < 0.5) { n = 200; len = 50; } else { n = 50; len = 300; }
    alphabet = 26;
  } else {
    n = 1 + Math.floor(rand() * 7);
    len = 1 + Math.floor(rand() * 5);
    alphabet = 1 + Math.floor(rand() * 4);
  }
  const base = Array.from({ length: len }, () => String.fromCharCode(97 + Math.floor(rand() * alphabet)));
  const strs = [base.join('')];
  // Every word is a shuffle of an earlier one, so all stay anagrams; one swap usually keeps it in a group.
  while (strs.length < n) {
    const chars = strs[Math.floor(rand() * strs.length)].split('');
    const swaps = rand() < 0.6 ? 1 : 1 + Math.floor(rand() * len);
    for (let s = 0; s < swaps; s++) {
      const i = Math.floor(rand() * len), j = Math.floor(rand() * len);
      [chars[i], chars[j]] = [chars[j], chars[i]];
    }
    strs.push(chars.join(''));
  }
  return [strs];
}
